def nb(g,i,j):
    # 3x3 neighborhood 4-count (excluding center) and center
    cnt=0
    for di in(-1,0,1):
        for dj in(-1,0,1):
            if di==dj==0: continue
            x,y=i+di,j+dj
            if 0<=x<len(g) and 0<=y<len(g[0]) and g[x][y]==4: cnt+=1
    return cnt
